/* Participant-owned content controls never grant moderation rights. */
function ownPhotoPosts(){const u=current();if(!u)return '';const photos=state.photos.filter(p=>p.submitted&&p.ownerId===u.id).slice().sort((a,b)=>b.id-a.id);return '<section class="section" id="my-photo-posts" tabindex="-1"><h2>自分の投稿写真</h2><p>自分の写真のタイトル・投稿者名・コメントを変更し、掲載を取り下げられます。取り下げた写真の再掲載は幹事にご相談ください。</p>'+(!photos.length?'<p class="empty">投稿した写真はまだありません。</p>':photos.map(p=>'<details class="panel" id="own-photo-'+p.id+'"><summary>'+esc(p.title)+' ／ '+(p.deleted?'取り下げ済み':p.published?'掲載中':'非公開')+'</summary>'+(p.deleted?'<p>この写真は取り下げ済みです。再掲載は幹事へご相談ください。</p>':'<img class="post-photo-preview" src="'+esc(p.src)+'" alt="'+esc(p.title)+'"><form data-own-photo="edit" data-id="'+p.id+'">'+field('title','写真のタイトル',p.title)+field('author','アルバムに表示する投稿者名',p.authorLabel)+'<label class="field">写真についてのコメント<textarea name="caption" maxlength="1000" rows="4">'+esc(p.caption)+'</textarea></label>'+field('reason','変更理由')+'<p class="error-text" role="alert"></p><button class="btn">投稿内容を保存</button></form><form data-own-photo="withdraw" data-id="'+p.id+'"><p>取り下げると、他の参加者は写真を閲覧できなくなります。</p>'+field('reason','取り下げ理由')+'<p class="error-text" role="alert"></p><button class="btn btn-outline">写真の掲載を取り下げる</button></form>')+'</details>').join(''))+'</section>';}
const ownPhotosBaseMy=myPage,ownPhotosBaseGallery=galleryPage;
myPage=function(){return ownPhotosBaseMy()+(current()?frame(ownPhotoPosts()):'');};
galleryPage=function(){const box=document.createElement('div');box.innerHTML=ownPhotosBaseGallery();box.querySelector('.button-row')?.insertAdjacentHTML('beforeend','<a class="btn btn-outline" href="#/my/photos">自分の投稿を編集・取り下げ</a>');return box.innerHTML;};
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset.ownPhoto)return;ev.preventDefault();ev.stopImmediatePropagation();try{const u=current();if(!u)throw new Error('ログインが必要です。');const d=Object.fromEntries(new FormData(f)),id=Number(f.dataset.id);change(s=>{if(f.dataset.ownPhoto==='edit')P.editOwn(s,id,d,u.id);else if(f.dataset.ownPhoto==='withdraw')P.withdrawOwn(s,id,d.reason,u.id);else throw new Error('操作が不正です。');});route();toast('自分の投稿と変更履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;}},true);
